CREATE OR REPLACE FUNCTION math_private.release_catalog(p_exam uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
